begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-0000-0000-00000000af01','zero-admin@test.local');
update profiles set role='admin' where user_id='00000000-0000-0000-0000-00000000af01';
insert into account_heads(code,name,account_type,is_cash_bank) values
 (89201,'Zero cash','asset',true),(89202,'Zero scheme','liability',false);
insert into customers(code,name) values(89201,'Zero ticket 1'),(89202,'Zero ticket 2');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000af01',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-00000000af01","role":"authenticated"}',true);
set local role authenticated;
set constraints all deferred;
select create_financial_year(2026);
create temporary table fixture(scheme integer,member integer,other_member integer);
insert into fixture(scheme) select id from create_kuri_scheme('Zero installment test',4000,2,20.4,'2026-10-01',null,89202);
update fixture set member=(select id from add_kuri_member((select scheme from fixture),89201,1));
update fixture set other_member=(select id from add_kuri_member((select scheme from fixture),89202,2));
select set_kuri_installment_amount((select scheme from fixture),2,0,'Waived',4000);
select is(kuri_installment_due((select scheme from fixture),2),0::numeric,'draft installment accepts zero as an explicit override');
select is((select is_custom from kuri_installment_amount_schedule((select scheme from fixture)) where installment_no=2),true,'zero is custom rather than falling back to the base amount');
select set_kuri_installment_amount((select scheme from fixture),2,null,'Restore base',0);
select is(kuri_installment_due((select scheme from fixture),2),4000::numeric,'zero override can reset to the base amount');
select activate_kuri_scheme((select scheme from fixture));
select set_kuri_installment_amount((select scheme from fixture),2,0,'Waived active installment',4000);
select is((select count(*) from kuri_installment_amount_history where scheme_id=(select scheme from fixture)),3::bigint,'zero changes and resets are audited');
select is(kuri_scheme_total_due((select scheme from fixture)),8000::numeric,'ticket total excludes zero dues');
select is((select balance from kuri_member_ledger((select scheme from fixture),(select member from fixture)) where installment_no=2),0::numeric,'zero installment has no unpaid balance');
select is((select amount_due from kuri_collection_status((select scheme from fixture),2) where member_id=(select member from fixture)),0::numeric,'collection screen returns zero dues');
select is((select count(*) from kuri_defaulters((select scheme from fixture),2)),0::bigint,'zero dues never create defaulters');
select is(record_kuri_bulk_payment((select scheme from fixture),2,'2026-10-03',null,89201),0,'bulk collection skips zero installments');
select is((select count(*) from kuri_payments where scheme_id=(select scheme from fixture)),0::bigint,'skipping zero creates no payment');
select record_kuri_payment((select scheme from fixture),(select member from fixture),1,3800,'2026-10-03',null,null,89201);
select record_kuri_receipt((select scheme from fixture),(select member from fixture),500,'2026-10-03',null,
 '00000000-0000-0000-0000-00000000af10',89201,'[{"installment_no":1,"amount":200},{"installment_no":3,"amount":300}]');
select is((select amount from kuri_payments where receipt_id='00000000-0000-0000-0000-00000000af10' and installment_no=1),200::numeric,'receipt clears arrears before the zero installment');
select is((select amount from kuri_payments where receipt_id='00000000-0000-0000-0000-00000000af10' and installment_no=3),300::numeric,'receipt skips zero and applies the remainder to the next payable installment');
select is((select count(*) from kuri_payments where scheme_id=(select scheme from fixture) and installment_no=2),0::bigint,'receipt never allocates a zero payment');
select is((select total_amount from vouchers where id=(select voucher_id from kuri_payments where receipt_id='00000000-0000-0000-0000-00000000af10' limit 1)),500::numeric,'receipt accounting amount stays exact across the gap');
select throws_ok($$select set_kuri_installment_amount((select scheme from fixture),2,100)$$,
 '22023','only future installments without receipts or lot draws can be changed','zero installment is locked once receipts reach later installments');
select record_kuri_receipt((select scheme from fixture),(select member from fixture),3700,'2026-10-03',null,null,89201);
select record_kuri_receipt((select scheme from fixture),(select other_member from fixture),8000,'2026-10-03',null,null,89201);
select draw_kuri_lot((select scheme from fixture),2,(select member from fixture));
select draw_kuri_lot((select scheme from fixture),3,(select other_member from fixture));
select mark_kuri_payout((select id from kuri_lots where scheme_id=(select scheme from fixture) and installment_no=2),'2026-10-03',89201);
select mark_kuri_payout((select id from kuri_lots where scheme_id=(select scheme from fixture) and installment_no=3),'2026-10-03',89201);
select is((select status from kuri_schemes where id=(select scheme from fixture)),'completed','completion does not require a receipt for the zero installment');
select is((select payout_amount from kuri_payout_schedule((select scheme from fixture)) where installment_no=2),6368::numeric,'zero collection dues leave payout calculation unchanged');
select finish();
rollback;
